
.body-layout {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-head {
  font-size: 0.88rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-pink-light);
  display: inline-block;
  margin-bottom: 4px;
  padding-bottom: 2px;
}

.body-grid {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.body-item {
  background: var(--c-cream);
  border: 1px solid var(--c-mist);
  padding: 6px 8px;
  border-left: 3px solid var(--c-pink-light);
}

.body-label {
  display: block;
  font-size: 0.72rem;
  font-weight: bold;
  color: var(--c-pink);
  margin-bottom: 2px;
}

.body-value {
  font-size: 0.82rem;
  color: var(--c-ink);
  line-height: 1.4;
}

.appearance-box {
  background: var(--c-cream);
  border: 1px solid var(--c-mist);
  padding: 8px;
  font-size: 0.82rem;
  line-height: 1.5;
  font-style: italic;
  color: var(--c-ink);
}
