
.card {
  width: 100%;
  max-width: 720px;
  background-color: var(--c-parchment);
  border: 2px solid var(--c-ink);
  box-shadow: 4px 4px 0px var(--c-shadow);
  display: flex;
  flex-direction: column;
  font-family: var(--font-main);
  color: var(--c-ink);
  font-size: 13px;
  line-height: 1.5;
  margin: 0 auto;
  border-radius: 2px;
}

.card.phase-xiuxian {
  border-color: var(--c-jade);
}
.card.phase-capture {
  border-color: #c9584c;
}
.card.phase-train {
  border-color: var(--c-pink);
}
.card.phase-fallen {
  border-color: #8b3a62;
}

.content-area {
  padding: 12px;
  min-height: 0;
}

.tab-pane {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-pane.active {
  display: block;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
