
.stats-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
  gap: 4px;
  padding: 8px 10px;
  background: var(--c-cream);
  border-bottom: 1.5px dashed var(--c-mist);
}

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.stat-label {
  font-size: 0.72rem;
  font-weight: bold;
  color: var(--c-ink);
}

.stat-track {
  width: 100%;
  height: 6px;
  background: var(--c-parchment);
  border: 1px solid var(--c-mist);
  border-radius: 3px;
  overflow: hidden;
}

.stat-fill {
  height: 100%;
  transition: width 0.4s ease;
  border-radius: 3px;
}

.stat-value {
  font-size: 0.68rem;
  color: var(--c-mist);
  font-family: var(--font-mono);
}
