
.corruption-layout {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.section-head {
  font-size: 0.88rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-pink);
  display: inline-block;
  margin-bottom: 2px;
  padding-bottom: 2px;
}

.bar-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.bar-item {
  background: var(--c-cream);
  border: 1px solid var(--c-mist);
  padding: 8px;
}

.bar-header {
  display: flex;
  justify-content: space-between;
  margin-bottom: 4px;
}

.bar-label {
  font-weight: bold;
  font-size: 0.82rem;
}

.bar-value {
  font-family: var(--font-mono);
  font-size: 0.78rem;
  color: var(--c-mist);
}

.bar-track {
  height: 8px;
  background: var(--c-parchment);
  border: 1px solid var(--c-mist);
  border-radius: 4px;
  overflow: hidden;
  margin-bottom: 4px;
}

.bar-fill {
  height: 100%;
  transition: width 0.5s ease;
  border-radius: 4px;
}

.bar-fill.reform {
  background: linear-gradient(90deg, var(--c-jade) 0%, var(--c-pink-light) 100%);
}
.bar-fill.common {
  background: linear-gradient(90deg, var(--c-gold) 0%, var(--c-pink) 100%);
}
.bar-fill.fallen {
  background: linear-gradient(90deg, var(--c-pink) 0%, #8b3a62 100%);
}

.bar-hint {
  font-size: 0.7rem;
  color: var(--c-mist);
  font-style: italic;
}

.secret-box {
  background: rgba(212, 98, 142, 0.08);
  border: 1px dashed var(--c-pink);
  padding: 8px;
}

.secret-label {
  display: block;
  font-size: 0.75rem;
  font-weight: bold;
  color: var(--c-pink);
  margin-bottom: 3px;
}

.secret-value {
  font-size: 0.78rem;
  color: var(--c-ink);
}
