
.inventory-layout {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-head {
  font-size: 0.88rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-gold);
  display: inline-block;
  margin-bottom: 4px;
  padding-bottom: 2px;
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-row {
  display: flex;
  align-items: center;
  border: 1px solid var(--c-mist);
  padding: 7px 8px;
  background: var(--c-cream);
  transition: transform 0.2s;
}

.item-row:hover {
  transform: translateX(4px);
  border-left: 3px solid var(--c-gold);
}

.item-icon {
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 8px;
  font-size: 1.1rem;
}

.item-detail {
  flex: 1;
}

.item-name {
  font-weight: bold;
  font-size: 0.85rem;
  display: block;
}

.item-desc {
  font-size: 0.72rem;
  color: var(--c-mist);
}

.item-count {
  background: var(--c-ink);
  color: var(--c-cream);
  padding: 2px 6px;
  font-size: 0.72rem;
  font-family: var(--font-mono);
}

.empty-state {
  text-align: center;
  color: var(--c-mist);
  padding: 16px;
  font-style: italic;
}
