
.char-layout {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 6px;
}

.info-item {
  padding: 4px 0;
  border-bottom: 1px dotted var(--c-mist);
}

.info-item.full {
  grid-column: 1 / -1;
}

.info-label {
  font-size: 0.72rem;
  color: var(--c-mist);
  display: block;
}

.info-value {
  font-size: 0.88rem;
  font-weight: bold;
}

.info-value.gold {
  color: var(--c-gold);
}
.info-value.pink {
  color: var(--c-pink);
}

.dao-ok {
  color: var(--c-jade);
}
.dao-shake {
  color: var(--c-gold);
}
.dao-break {
  color: #c9584c;
}
.dao-sleep {
  color: var(--c-mist);
}
.dao-reverse {
  color: var(--c-pink);
}

.section {
  margin-top: 4px;
}

.section-head {
  font-size: 0.88rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-jade);
  display: inline-block;
  margin-bottom: 6px;
  padding-bottom: 2px;
}

.section-head.pink {
  border-bottom-color: var(--c-pink);
}

.title-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.title-tag {
  background: var(--c-cream);
  border: 1px solid var(--c-gold);
  padding: 4px 8px;
}

.title-name {
  font-weight: bold;
  font-size: 0.8rem;
  color: var(--c-gold);
  margin-right: 4px;
}

.title-effect {
  font-size: 0.72rem;
  color: var(--c-mist);
}

.attire-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 5px;
}

.attire-item {
  border: 1px solid var(--c-mist);
  padding: 5px;
  background: var(--c-cream);
}

.attire-slot {
  font-size: 0.7rem;
  color: var(--c-mist);
  display: block;
  font-weight: bold;
}

.attire-desc {
  font-size: 0.8rem;
}

.slave-section {
  background: rgba(212, 98, 142, 0.06);
  padding: 8px;
  border: 1px dashed var(--c-pink);
}

@media (max-width: 500px) {
  .info-grid {
    grid-template-columns: 1fr;
  }
  .attire-grid {
    grid-template-columns: 1fr;
  }
}
