
.relation-layout {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.section-head {
  font-size: 0.88rem;
  font-weight: bold;
  border-bottom: 2px solid var(--c-jade);
  display: inline-block;
  margin-bottom: 4px;
  padding-bottom: 2px;
}

.relation-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.relation-card {
  background: var(--c-cream);
  border: 1px solid var(--c-mist);
  padding: 8px;
  border-left: 3px solid var(--c-jade);
}

.relation-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.relation-name {
  font-weight: bold;
  font-size: 0.88rem;
}

.relation-type {
  font-size: 0.72rem;
  background: var(--c-parchment);
  border: 1px solid var(--c-mist);
  padding: 1px 6px;
  color: var(--c-mist);
}

.relation-bar-row {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
}

.relation-favor-label {
  font-size: 0.7rem;
  color: var(--c-mist);
  width: 24px;
}

.relation-bar {
  flex: 1;
  height: 6px;
  background: var(--c-parchment);
  border: 1px solid var(--c-mist);
  border-radius: 3px;
  overflow: hidden;
}

.relation-fill {
  height: 100%;
  transition: width 0.4s ease;
  border-radius: 3px;
}

.relation-fill.favor-high {
  background: var(--c-jade);
}
.relation-fill.favor-mid {
  background: var(--c-jade-light);
}
.relation-fill.favor-low {
  background: var(--c-mist);
}
.relation-fill.favor-neg {
  background: #c9584c;
}

.relation-favor-value {
  font-size: 0.7rem;
  font-family: var(--font-mono);
  color: var(--c-mist);
  width: 28px;
  text-align: right;
}

.relation-impression {
  font-size: 0.76rem;
  color: var(--c-mist);
  font-style: italic;
  padding-top: 2px;
  border-top: 1px dotted var(--c-mist);
}

.empty-state {
  text-align: center;
  color: var(--c-mist);
  padding: 16px;
  font-style: italic;
}
